--
-- Table structure for table `comment_answer`
--

DROP TABLE IF EXISTS `comment_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comment_answer` (
  `comment_answer_no` int NOT NULL AUTO_INCREMENT COMMENT '댓글답안 고유번호',
  `board_no` int NOT NULL COMMENT '게시글 고유번호 (board.board_no 참조)',
  `id` varchar(50) NOT NULL COMMENT '작성자 아이디 (user.id 참조)',
  `comment_answer_content` text NOT NULL COMMENT '댓글답안내용',
  `comment_like_count` int NOT NULL DEFAULT '0' COMMENT '댓글 추천수',
  `comment_dislike_count` int NOT NULL DEFAULT '0' COMMENT '댓글 비추천수',
  `comment_answer_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '댓글답안작성일시',
  `comment_answer_updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '댓글답안 수정일시',
  `comment_answer_type` int NOT NULL COMMENT '1: 댓글 2:답안',
  `answer_accepted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '답안채택여부',
  PRIMARY KEY (`comment_answer_no`),
  KEY `fk_ca_board_no` (`board_no`),
  KEY `fk_ca_user_id` (`id`),
  CONSTRAINT `fk_ca_board_no` FOREIGN KEY (`board_no`) REFERENCES `board` (`board_no`),
  CONSTRAINT `fk_ca_user_id` FOREIGN KEY (`id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `comment_answer`
--

LOCK TABLES `comment_answer` WRITE;
/*!40000 ALTER TABLE `comment_answer` DISABLE KEYS */;
