  `last_message_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '마지막 메시지 전송 일시',
  PRIMARY KEY (`room_no`),
  UNIQUE KEY `uq_room_participants` (`user_id_a`,`user_id_b`),
  KEY `fk_room_user_b` (`user_id_b`),
  CONSTRAINT `fk_room_user_a` FOREIGN KEY (`user_id_a`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_room_user_b` FOREIGN KEY (`user_id_b`) REFERENCES `user` (`id`)
